import json
import re

def parse_skill_md(filepath="SKILL.md"):
    with open(filepath, "r", encoding="utf-8") as f:
        content = f.read()

    lines = content.split(chr(10))

    # Extract project name from first heading
    project_name = lines[0].lstrip("# ")

    # Extract version and license
    version = ""
    license_val = ""
    for line in lines:
        if "**Version:**" in line:
            version = line.split("**Version:**")[1].strip()
        elif "**License:**" in line:
            license_val = line.split("**License:**")[1].strip()

    # Extract supported models
    models = []
    in_models = False
    for line in lines:
        if "## Supported Models" in line:
            in_models = True
            continue
        if in_models:
            stripped = line.strip()
            if stripped.startswith("- "):
                models.append(stripped[2:])
            elif stripped and not stripped.startswith("-"):
                break

    return {
        "project_name": project_name,
        "version": version,
        "license": license_val,
        "supported_models": models
    }

def main():
    summary = parse_skill_md("SKILL.md")
    with open("output.json", "w", encoding="utf-8") as f:
        json.dump(summary, f, indent=2)
    print("Summary written to output.json")

if __name__ == "__main__":
    main()
